(function(){"use strict";app.factory("proveedorService",function(t){const e="Compra/Proveedor/",n={},r=t.get("mainService");return n.get=function(){},n.save=function(t){return r.getData("post",`${e}?json=${JSON.stringify(t)}`,null,!0)},n.update=function(t,n){return r.getData("put",`${e}${t}?json=${JSON.stringify(n)}`,null,!0)},n.delete=function(t){return r.getData("delete",e+t,null,!0)},n}),app.factory("categoriaCompraService",function(t){const e="Compra/CategoriaCompra/",n=t.get("mainService"),r={get:t=>n.getData("get",e+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let e=JSON.parse(t.payload);return e}}),post:t=>n.getData("post",e+"?json="+JSON.stringify(t),null,!0),put:(t,r)=>n.getData("put",e+t+"?json="+JSON.stringify(r),null,!0),delete:t=>n.getData("delete",e+""+t,null,!0)};return r})})(window.angular);